<template><ClinicalTrainingAssistant v-if="compatible" :key="identity" :initial-references="references" :initial-objective="initialInput.objective??''" :active="active"/><p v-else role="status">当前功能配置或引用不属于明确本人练习的教学反馈范围；不能回退到通用模型输入或读取患者资料。</p></template>
<script setup>
import{computed}from'vue';import{useStore}from'vuex';import{trainingCanonical,trainingKeys,trainingId}from'@/api/ai/clinicalTrainingCore';import{verifyTrainingFeature,trainingTaskObjectives}from'@/api/ai/clinicalTrainingTasks';import{trainingStaffRoles}from'@/api/ai/clinicalTrainingSources';import ClinicalTrainingAssistant from'./ClinicalTrainingAssistant.vue';
const props=defineProps({feature:{type:Object,default:null},featureKey:{type:String,default:''},initialInput:{type:Object,default:()=>({})},patientId:{type:Number,default:null},encounterRef:{type:String,default:''},pharmaceuticalId:{type:Number,default:null},active:{type:Boolean,default:true}}),store=useStore();
const validInput=computed(()=>trainingKeys(props.initialInput,[])||trainingKeys(props.initialInput,['clinical_training_submission_id'])&&trainingId(props.initialInput.clinical_training_submission_id)||trainingKeys(props.initialInput,['clinical_training_submission_id','objective'])&&trainingId(props.initialInput.clinical_training_submission_id)&&Object.hasOwn(trainingTaskObjectives,props.initialInput.objective));
const references=computed(()=>validInput.value&&Object.hasOwn(props.initialInput,'clinical_training_submission_id')?{clinical_training_submission_id:props.initialInput.clinical_training_submission_id}:null);
const compatible=computed(()=>props.featureKey==='clinical_training'&&verifyTrainingFeature(props.feature)&&validInput.value&&props.patientId===null&&(props.encounterRef===null||props.encounterRef==='')&&props.pharmaceuticalId===null&&typeof store.state.user?.accessToken==='string'&&store.state.user.accessToken.length>0&&Array.isArray(store.state.user.permissions)&&store.state.user.permissions.some(role=>trainingStaffRoles.includes(role)&&props.feature.allowed_roles.includes(role)));
const identity=computed(()=>trainingCanonical([props.feature,props.initialInput,props.patientId,props.encounterRef,props.pharmaceuticalId,props.active,store.state.user?.accessToken,store.state.user?.username,store.state.user?.permissions]));
</script>
